"use client";
import {FormEvent,useCallback,useEffect,useMemo,useState} from "react";
import Link from "next/link";
import Image from "next/image";
import {ArrowRight,Car,FileCheck2,Flame,HeartPulse,House,Plane,RefreshCw,ShieldCheck,Ship,Users,Upload,Plus,AlertCircle} from "lucide-react";
import {insuranceService,InsuranceAgency,InsuranceCase,InsuranceClaim,InsuranceCompany,InsuranceDocument,InsurancePaymentOption,InsurancePolicy,InsuranceProduct,InsuranceRenewalJourney,MarineIdfOcrResult} from "@/services/insurance.service";
import {InsuranceBrandLogo} from "@/components/insurance/InsuranceBrandLogo";
import {apiErrorMessage} from "@/lib/api-error";
